"""Placement, winner detection, match results and one-time reward granting.

Reward numbers are local development values, not original Rules of Survival economy data:
  experience = 100 + 20 * kills + int(survival_seconds / 10) + placement bonus
  currency   = 10 * kills + placement bonus
  placement bonus (top 10 only): experience (11 - placement) * 10, currency (11 - placement) * 5
"""

from collections.abc import Callable

from solo_engine.model import Participant, ParticipantResult, SoloMatch

BASE_EXPERIENCE = 100
EXPERIENCE_PER_KILL = 20
SURVIVAL_SECONDS_PER_EXPERIENCE = 10
CURRENCY_PER_KILL = 10
BONUS_PLACES = 10
EXPERIENCE_PLACE_BONUS = 10
CURRENCY_PLACE_BONUS = 5


def assign_placement(match: SoloMatch, participant: Participant) -> int:
    """Set and return the placement of a just-eliminated participant: alive count + 1.

    When several participants fall in the same tick, each later one takes the next free place
    below, so placements stay unique.
    """
    if participant.placement is not None:
        return participant.placement
    taken = {p.placement for p in match.participants.values() if p.placement is not None}
    placement = len(match.alive()) + 1
    while placement in taken:
        placement += 1
    participant.placement = placement
    return placement


def check_winner(match: SoloMatch) -> str | None:
    """Return the winner id once at most one participant is alive, else None.

    With nobody alive (simultaneous last eliminations) the last id in `elimination_order` wins,
    unless that participant left: a forfeit never wins, so the match has no winner.
    A match that started with a single participant (bot_count=0) stays playable: no winner is
    declared until something has been eliminated (the zone, or leaving).
    """
    if match.winner_id is not None:
        return match.winner_id
    if len(match.participants) <= 1 and not match.elimination_order:
        return None
    alive = match.alive()
    if len(alive) > 1:
        return None
    if alive:
        winner = alive[0]
    elif match.elimination_order:
        winner = match.participants[match.elimination_order[-1]]
        if winner.eliminated_cause == "left":
            return None
    else:
        return None
    for other in match.participants.values():
        if other is not winner and other.placement == 1:
            other.placement = winner.placement if winner.placement not in (None, 1) else 2
    winner.placement = 1
    match.winner_id = winner.participant_id
    return winner.participant_id


def place_survivors(match: SoloMatch) -> None:
    """Give alive participants without a placement the best free places, unique.

    Used when a match ends without a winner (every human left, or the last one forfeited):
    survivors take places 1..k ordered by health (highest first), then participant id.
    """
    survivors = sorted(
        (p for p in match.participants.values() if p.alive and p.placement is None),
        key=lambda p: (-p.health, p.participant_id),
    )
    taken = {p.placement for p in match.participants.values() if p.placement is not None}
    place = 1
    for p in survivors:
        while place in taken:
            place += 1
        p.placement = place
        taken.add(place)


def placement_bonus(placement: int) -> tuple[int, int]:
    """(experience, currency) bonus for a placement; zero outside the top 10."""
    if 1 <= placement <= BONUS_PLACES:
        place_value = BONUS_PLACES + 1 - placement
        return place_value * EXPERIENCE_PLACE_BONUS, place_value * CURRENCY_PLACE_BONUS
    return 0, 0


def compute_rewards(kills: int, survival_seconds: float, placement: int) -> tuple[int, int]:
    """(experience, currency) for one participant."""
    xp_bonus, currency_bonus = placement_bonus(placement)
    experience = (
        BASE_EXPERIENCE
        + EXPERIENCE_PER_KILL * kills
        + int(survival_seconds / SURVIVAL_SECONDS_PER_EXPERIENCE)
        + xp_bonus
    )
    currency = CURRENCY_PER_KILL * kills + currency_bonus
    return experience, currency


def survival_seconds(match: SoloMatch, participant: Participant) -> float:
    """Seconds survived in PLAYING; 0 when the match never reached PLAYING."""
    if match.started_playing_at is None:
        return 0.0
    start = match.started_playing_at
    end = participant.eliminated_at if participant.eliminated_at is not None else match.clock
    return max(0.0, end - start)


def build_results(match: SoloMatch) -> list[ParticipantResult]:
    """One result per participant, ordered by placement."""
    place_survivors(match)  # no duplicate placements, even without a winner
    results: list[ParticipantResult] = []
    for p in match.participants.values():
        winner = match.winner_id is not None and p.participant_id == match.winner_id
        placement = p.placement if p.placement is not None else 1
        survived = survival_seconds(match, p)
        experience, currency = compute_rewards(p.stats.kills, survived, placement)
        results.append(
            ParticipantResult(
                participant_id=p.participant_id,
                is_bot=p.is_bot,
                placement=placement,
                kills=p.stats.kills,
                damage_dealt=p.stats.damage_dealt,
                survival_seconds=survived,
                experience=experience,
                currency=currency,
                winner=winner,
            )
        )
    results.sort(key=lambda r: (r.placement, r.participant_id))
    return results


def grant_rewards_once(match: SoloMatch, grant: Callable[[ParticipantResult], None]) -> bool:
    """Call `grant` for each human result, once per match. Returns False if already granted.

    The flag is set before any grant runs, so a failing grant is not retried (at most once).
    """
    if match.rewards_granted:
        return False
    match.rewards_granted = True
    if match.results is None:
        match.results = build_results(match)
    for result in match.results:
        if not result.is_bot:
            grant(result)
    return True


def result_view(result: ParticipantResult) -> dict:
    """JSON-friendly view of one result."""
    return {
        "participant_id": result.participant_id,
        "is_bot": result.is_bot,
        "placement": result.placement,
        "kills": result.kills,
        "damage_dealt": round(result.damage_dealt, 2),
        "survival_seconds": round(result.survival_seconds, 2),
        "experience": result.experience,
        "currency": result.currency,
        "winner": result.winner,
    }
